"""Claims must preserve source units and never turn missing facts into allegations."""

from types import SimpleNamespace

import pytest

from buyer.claims import ClaimBank


def notice_case(facts=None):
    return {
        "type": "price_increase",
        "trigger_doc": "doc:letter",
        "refs": ["doc:letter", "ctr:contract"],
        "parts": [],
        "buyer": {},
        "facts": facts or {},
    }


def test_unresolved_letter_does_not_invent_a_notice_violation():
    pkg = SimpleNamespace(lookup=lambda ref: None)
    bank = ClaimBank(pkg, notice_case())
    assert bank.foreign
    assert bank.for_supplier("sup:new", 10) == []


@pytest.mark.parametrize(
    "facts",
    [
        {"doc:letter": {"days": 30}},
        {"ctr:contract": {"days": 90}},
        {"doc:letter": {"days": 90}, "ctr:contract": {"days": 90}},
        {"doc:letter": {"days": 100}, "ctr:contract": {"days": 90}},
    ],
)
def test_notice_requires_both_facts_and_actual_shortfall(facts):
    assert ClaimBank(None, notice_case(facts)).notice("sup:new") is None


def test_documented_notice_shortfall_keeps_both_numbers_and_sources():
    bank = ClaimBank(None, notice_case({"doc:letter": {"days": 51}, "ctr:contract": {"days": 90}}))
    claim = bank.notice("sup:new")
    assert claim["ids"] == ["doc:letter", "ctr:contract"]
    assert "51 days' notice (doc:letter)" in claim["text"]
    assert "90 days (ctr:contract)" in claim["text"]


def test_quality_claim_does_not_format_thousands_as_decimal_comma():
    case = {"facts": {"sc:new@2026Q3": {"ppm": 2637, "quarter": "2026Q3"}}}
    claim = ClaimBank(None, case).scorecard("sup:new", quality=True)
    assert "2637 ppm" in claim["text"]
    assert "2,637" not in claim["text"]
    assert claim["ids"] == ["sc:new@2026Q3"]


def history_bank(units):
    facts = {f"po:{i}": {"unit_price": 500, "price_unit": unit} for i, unit in enumerate(units)}
    pkg = SimpleNamespace(
        lookup=facts.get,
        query=lambda sql, params: [{"id": ref} for ref in facts],
    )
    return ClaimBank(pkg, {})


def test_order_claim_compares_per_piece_but_preserves_recorded_price():
    bank = history_bank([100, 100])
    claim = bank.order_history("part:new", "sup:new", quote=6)
    assert "EUR 500.00 per 100 units" in claim["text"]
    assert bank.order_history("part:new", "sup:new", quote=4) is None


def test_mixed_price_units_are_not_labeled_as_one_unit():
    assert history_bank([100, 1]).order_history("part:new", "sup:new", quote=6) is None


def test_rival_quote_preserves_price_basis_and_omits_higher_per_piece_quote():
    case = {
        "refs": ["quote:rival"],
        "facts": {"quote:rival": {"part": "part:new", "supplier": "sup:rival", "unit_price": 500, "price_unit": 100}},
    }
    bank = ClaimBank(None, case)
    assert "EUR 500.00 per 100 units" in bank.rival_quote("part:new", "sup:new", 6)[0]["text"]
    assert bank.rival_quote("part:new", "sup:new", 4) == []

